INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0001-000000000001', 'b0000001-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 1, 'vocabulario-de-rutina-diaria', '{"es": "Vocabulario de Rutina Diaria", "en": "Daily Routine Vocabulary"}'::jsonb, '{"es": "Aprende los verbos y expresiones que describen las actividades de un día normal.", "en": "Learn the verbs and expressions that describe the activities of a normal day."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "Todos tenemos una rutina: cosas que hacemos casi todos los días, como despertarnos, ir al trabajo o cenar. En esta lección vas a aprender los verbos en inglés para describir tu rutina diaria, usando el presente simple que ya conoces. Por ejemplo: ''I wake up at 7 o''clock'' (Me despierto a las 7).", "sections": [{"type": "table", "title": "VERBOS DE RUTINA DIARIA", "headers": ["Inglés", "Español"], "rows": [["wake up", "despertarse"], ["get up", "levantarse"], ["take a shower", "ducharse"], ["get dressed", "vestirse"], ["have breakfast", "desayunar"], ["go to work / go to school", "ir al trabajo / ir a la escuela"], ["have lunch", "almorzar"], ["come home", "volver a casa"], ["have dinner", "cenar"], ["do homework", "hacer la tarea"], ["watch TV", "ver la televisión"], ["go to bed", "irse a la cama"]]}, {"type": "note", "variant": "tip", "text": "Muchas de estas expresiones usan ''have'' o ''get'' en lugar de un verbo específico en español: ''have breakfast/lunch/dinner'' (no existe un verbo único como ''desayunar'' para cada comida) y ''get up/get dressed'' (levantarse/vestirse). Apréndelas como frases completas, no palabra por palabra."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0001-0001-000000000001', 'b0000002-0000-0000-0001-000000000001', 1, 'flashcard', '{"text": "wake up", "subtext": "verb"}'::jsonb, '{"text": "despertarse", "phonetic": "/weɪk ʌp/"}'::jsonb, NULL, NULL, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0002-000000000001', 'b0000002-0000-0000-0001-000000000001', 2, 'flashcard', '{"text": "take a shower", "subtext": "verb phrase"}'::jsonb, '{"text": "ducharse", "phonetic": "/teɪk ə ˈʃaʊ.ər/"}'::jsonb, NULL, NULL, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0003-000000000001', 'b0000002-0000-0000-0001-000000000001', 3, 'flashcard', '{"text": "do homework", "subtext": "verb phrase"}'::jsonb, '{"text": "hacer la tarea", "phonetic": "/duː ˈhoʊm.wɜːrk/"}'::jsonb, NULL, NULL, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0004-000000000001', 'b0000002-0000-0000-0001-000000000001', 4, 'word_match', '{"text": "Match each routine verb with its translation"}'::jsonb, '{"pairs": [{"en": "get up", "es": "levantarse"}, {"en": "get dressed", "es": "vestirse"}, {"en": "have lunch", "es": "almorzar"}, {"en": "go to bed", "es": "irse a la cama"}]}'::jsonb, NULL, NULL, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0005-000000000001', 'b0000002-0000-0000-0001-000000000001', 5, 'word_match', '{"text": "Match each routine verb with its translation"}'::jsonb, '{"pairs": [{"en": "have breakfast", "es": "desayunar"}, {"en": "come home", "es": "volver a casa"}, {"en": "have dinner", "es": "cenar"}, {"en": "watch TV", "es": "ver la televisión"}]}'::jsonb, NULL, NULL, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0006-000000000001', 'b0000002-0000-0000-0001-000000000001', 6, 'multiple_choice', '{"text": "Which expression means ''ducharse''?"}'::jsonb, '{"text": "take a shower"}'::jsonb, '["get dressed", "wake up", "do homework"]'::jsonb, '{"es": "''Take a shower'' significa ducharse."}'::jsonb, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0007-000000000001', 'b0000002-0000-0000-0001-000000000001', 7, 'multiple_choice', '{"text": "What do you say for ''ir al trabajo''?"}'::jsonb, '{"text": "go to work"}'::jsonb, '["go to bed", "come home", "have lunch"]'::jsonb, '{"es": "''Go to work'' significa ir al trabajo."}'::jsonb, '{"vocab:daily_routine"}'),
('b0000003-0001-0001-0008-000000000001', 'b0000002-0000-0000-0001-000000000001', 8, 'fill_blank', '{"text": "I ___ at 7 o''clock every morning."}'::jsonb, '{"text": "wake up", "accepted": ["wake up", "get up"]}'::jsonb, NULL, '{"es": "''Wake up'' (o ''get up'') describe el momento de despertarse por la mañana."}'::jsonb, '{"vocab:daily_routine"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0001-000000000002', 'b0000001-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 2, 'adverbios-de-frecuencia', '{"es": "Adverbios de Frecuencia", "en": "Adverbs of Frequency"}'::jsonb, '{"es": "Aprende a decir con qué frecuencia haces algo usando always, usually, often, sometimes, rarely y never.", "en": "Learn to say how often you do something using always, usually, often, sometimes, rarely, and never."}'::jsonb, 'grammar', 22, 14, '{"intro": "Los adverbios de frecuencia indican con qué frecuencia pasa algo: siempre, normalmente, a veces, nunca... Se usan con el presente simple, que ya conoces, y solo cambian una cosa: dónde se colocan en la oración.", "sections": [{"type": "table", "title": "ADVERBIOS DE FRECUENCIA", "headers": ["Inglés", "Español", "Frecuencia aproximada"], "rows": [["always", "siempre", "100%"], ["usually", "normalmente / generalmente", "~80%"], ["often", "a menudo", "~60%"], ["sometimes", "a veces", "~40%"], ["rarely / seldom", "rara vez / casi nunca", "~10%"], ["never", "nunca", "0%"]]}, {"type": "explanation", "title": "DÓNDE SE COLOCA EL ADVERBIO", "text": "La regla es: el adverbio de frecuencia va ANTES del verbo principal, pero DESPUÉS del verbo ''to be''. Ejemplos: ''I usually wake up at 7'' (el adverbio va antes de ''wake up''). ''She is always tired in the morning'' (el adverbio va después de ''is''). ''We never watch TV at night.'' ''He is often late.''"}, {"type": "note", "variant": "tip", "text": "Truco rápido: si la oración tiene ''to be'' (am/is/are), el adverbio va justo después. Si tiene cualquier otro verbo, el adverbio va justo antes de ese verbo."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0001-0001-000000000001', 'b0000002-0000-0000-0001-000000000002', 1, 'multiple_choice', '{"text": "Choose the correct sentence."}'::jsonb, '{"text": "I usually have breakfast at 8."}'::jsonb, '["I have usually breakfast at 8.", "Usually I have breakfast at 8, always.", "I have breakfast usually at 8."]'::jsonb, '{"es": "''Usually'' va antes del verbo principal ''have''."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0002-0001-0002-000000000001', 'b0000002-0000-0000-0001-000000000002', 2, 'multiple_choice', '{"text": "Choose the correct sentence."}'::jsonb, '{"text": "She is always tired after work."}'::jsonb, '["She always is tired after work.", "She tired always is after work.", "Always she is tired after work."]'::jsonb, '{"es": "Con el verbo ''to be'' (is), el adverbio va después: ''is always''."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0002-0001-0003-000000000001', 'b0000002-0000-0000-0001-000000000002', 3, 'multiple_choice', '{"text": "Which word means 0% frequency?"}'::jsonb, '{"text": "never"}'::jsonb, '["always", "often", "sometimes"]'::jsonb, '{"es": "''Never'' significa nunca, 0% de frecuencia."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0002-0001-0004-000000000001', 'b0000002-0000-0000-0001-000000000002', 4, 'fill_blank', '{"text": "We ___ go to bed early on weekends."}'::jsonb, '{"text": "rarely", "accepted": ["rarely", "seldom", "never", "sometimes", "often", "usually", "always"]}'::jsonb, NULL, '{"es": "Cualquier adverbio de frecuencia funciona aquí antes del verbo principal ''go''."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0002-0001-0005-000000000001', 'b0000002-0000-0000-0001-000000000002', 5, 'fill_blank', '{"text": "He is ___ late for school."}'::jsonb, '{"text": "often", "accepted": ["often", "always", "usually", "sometimes", "never", "rarely"]}'::jsonb, NULL, '{"es": "Con ''to be'' (is), el adverbio se coloca justo después del verbo."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0002-0001-0006-000000000001', 'b0000002-0000-0000-0001-000000000002', 6, 'translation', '{"text": "Ella siempre desayuna a las siete."}'::jsonb, '{"text": "She always has breakfast at seven.", "accepted": ["She always has breakfast at seven.", "She always has breakfast at 7."]}'::jsonb, NULL, NULL, '{"grammar:frequency_adverbs","vocab:daily_routine"}'),
('b0000003-0002-0001-0007-000000000001', 'b0000002-0000-0000-0001-000000000002', 7, 'translation', '{"text": "Nosotros nunca vemos la televisión por la mañana."}'::jsonb, '{"text": "We never watch TV in the morning.", "accepted": ["We never watch TV in the morning."]}'::jsonb, NULL, NULL, '{"grammar:frequency_adverbs","vocab:daily_routine"}'),
('b0000003-0002-0001-0008-000000000001', 'b0000002-0000-0000-0001-000000000002', 8, 'error_correction', '{"text": "I usually am tired on Mondays.", "error_word": "usually am"}'::jsonb, '{"text": "am usually"}'::jsonb, '["always usually", "am always usually", "usually be"]'::jsonb, '{"es": "Con ''to be'' (am) el adverbio va después del verbo: ''am usually'', no ''usually am''."}'::jsonb, '{"grammar:frequency_adverbs"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0001-000000000003', 'b0000001-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 3, 'preguntas-how-often', '{"es": "Preguntas sobre Rutinas: How Often...?", "en": "Questions about Routines: How Often...?"}'::jsonb, '{"es": "Aprende a preguntar con qué frecuencia hace algo alguien, y a responder con expresiones de frecuencia.", "en": "Learn to ask how often someone does something, and to answer with frequency expressions."}'::jsonb, 'grammar', 22, 14, '{"intro": "Para preguntar con qué frecuencia pasa algo, usamos ''How often...?'' junto con el presente simple que ya conoces: ''How often do you watch TV?'' (¿Con qué frecuencia ves la televisión?). Las respuestas pueden usar un adverbio de frecuencia (''I often watch TV'') o una expresión de frecuencia más específica.", "sections": [{"type": "table", "title": "EXPRESIONES DE FRECUENCIA", "headers": ["Inglés", "Español"], "rows": [["every day", "todos los días"], ["once a week", "una vez a la semana"], ["twice a week", "dos veces a la semana"], ["three times a month", "tres veces al mes"], ["on weekends", "los fines de semana"], ["on Mondays", "los lunes"]]}, {"type": "explanation", "title": "CÓMO SE FORMA LA PREGUNTA", "text": "''How often'' va al inicio, seguido del auxiliar do/does y el sujeto, igual que cualquier pregunta de presente simple: ''How often do you go to the gym?'' / ''How often does she call her mother?''. Las expresiones de frecuencia (once a week, on weekends...) suelen ir al final de la respuesta."}, {"type": "note", "variant": "tip", "text": "''Once'' = una vez, ''twice'' = dos veces. A partir de tres, se usa ''three times'', ''four times'', etc. — siempre con la palabra ''times''."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0001-0001-000000000001', 'b0000002-0000-0000-0001-000000000003', 1, 'multiple_choice', '{"text": "Choose the correct question."}'::jsonb, '{"text": "How often do you go to the gym?"}'::jsonb, '["How often you go to the gym?", "How often does you go to the gym?", "How often you do go to the gym?"]'::jsonb, '{"es": "Con ''you'' el auxiliar correcto es ''do'': ''How often do you...?''"}'::jsonb, '{"grammar:questions","grammar:frequency_adverbs"}'),
('b0000003-0003-0001-0002-000000000001', 'b0000002-0000-0000-0001-000000000003', 2, 'multiple_choice', '{"text": "Choose the correct question."}'::jsonb, '{"text": "How often does she call her mother?"}'::jsonb, '["How often do she call her mother?", "How often she calls her mother?", "How often does she calls her mother?"]'::jsonb, '{"es": "Con ''she'' el auxiliar es ''does'', y el verbo principal vuelve a la forma base: ''call''."}'::jsonb, '{"grammar:questions"}'),
('b0000003-0003-0001-0003-000000000001', 'b0000002-0000-0000-0001-000000000003', 3, 'multiple_choice', '{"text": "What does ''twice a week'' mean?"}'::jsonb, '{"text": "dos veces a la semana"}'::jsonb, '["una vez a la semana", "tres veces a la semana", "todos los días"]'::jsonb, '{"es": "''Twice'' significa dos veces."}'::jsonb, '{"vocab:frequency_expressions"}'),
('b0000003-0003-0001-0004-000000000001', 'b0000002-0000-0000-0001-000000000003', 4, 'fill_blank', '{"text": "___ often do you do your homework?"}'::jsonb, '{"text": "How", "accepted": ["How"]}'::jsonb, NULL, '{"es": "La pregunta de frecuencia empieza con ''How often''."}'::jsonb, '{"grammar:questions"}'),
('b0000003-0003-0001-0005-000000000001', 'b0000002-0000-0000-0001-000000000003', 5, 'fill_blank', '{"text": "I go to the dentist ___ a year."}'::jsonb, '{"text": "once", "accepted": ["once", "twice"]}'::jsonb, NULL, '{"es": "''Once a year'' significa una vez al año."}'::jsonb, '{"vocab:frequency_expressions"}'),
('b0000003-0003-0001-0006-000000000001', 'b0000002-0000-0000-0001-000000000003', 6, 'translation', '{"text": "¿Con qué frecuencia limpias tu casa?"}'::jsonb, '{"text": "How often do you clean your house?", "accepted": ["How often do you clean your house?"]}'::jsonb, NULL, NULL, '{"grammar:questions"}'),
('b0000003-0003-0001-0007-000000000001', 'b0000002-0000-0000-0001-000000000003', 7, 'translation', '{"text": "Voy al gimnasio tres veces a la semana."}'::jsonb, '{"text": "I go to the gym three times a week.", "accepted": ["I go to the gym three times a week."]}'::jsonb, NULL, NULL, '{"vocab:frequency_expressions"}'),
('b0000003-0003-0001-0008-000000000001', 'b0000002-0000-0000-0001-000000000003', 8, 'word_bank_fill', '{"text": "How often ___ you watch TV on weekends?"}'::jsonb, '{"answers": ["do"]}'::jsonb, '["does", "are"]'::jsonb, '{"es": "Con ''you'' el auxiliar correcto es ''do''."}'::jsonb, '{"grammar:questions"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0001-000000000004', 'b0000001-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 4, 'describir-tu-rutina-y-la-de-otros', '{"es": "Describir tu Rutina y la de Otros", "en": "Describing Your Routine and Other People''s"}'::jsonb, '{"es": "Combina el vocabulario de rutina, los adverbios de frecuencia y la tercera persona para describir tu día a día y el de otras personas.", "en": "Combine routine vocabulary, adverbs of frequency, and the third person to describe your day and other people''s."}'::jsonb, 'mixed', 25, 15, '{"intro": "Ya sabes los verbos de rutina, los adverbios de frecuencia y cómo preguntar con ''How often''. Ahora vas a juntar todo para describir tanto tu propia rutina como la de otra persona, recordando añadir la -s en tercera persona: ''She usually gets up early. She never skips breakfast.''", "sections": [{"type": "note", "variant": "tip", "text": "No olvides la -s en tercera persona con he/she/it: ''wake up'' → ''wakes up'', ''go'' → ''goes'', ''have'' → ''has''. El adverbio de frecuencia no cambia esta regla."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0004-0001-0001-000000000001', 'b0000002-0000-0000-0001-000000000004', 1, 'multiple_choice', '{"text": "Choose the correct sentence about a third person."}'::jsonb, '{"text": "She usually gets up at six."}'::jsonb, '["She usually get up at six.", "She get usually up at six.", "She usually getting up at six."]'::jsonb, '{"es": "Con ''she'' el verbo lleva -s: ''gets up''; ''usually'' va antes del verbo principal."}'::jsonb, '{"grammar:frequency_adverbs","vocab:daily_routine"}'),
('b0000003-0004-0001-0002-000000000001', 'b0000002-0000-0000-0001-000000000004', 2, 'multiple_choice', '{"text": "Choose the correct sentence."}'::jsonb, '{"text": "My brother never skips breakfast."}'::jsonb, '["My brother skips never breakfast.", "My brother never skip breakfast.", "Never my brother skips breakfast."]'::jsonb, '{"es": "Con ''my brother'' (tercera persona) el verbo lleva -s: ''skips''."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0004-0001-0003-000000000001', 'b0000002-0000-0000-0001-000000000004', 3, 'fill_blank', '{"text": "He ___ (have) dinner with his family every night."}'::jsonb, '{"text": "has", "accepted": ["has"]}'::jsonb, NULL, '{"es": "''Have'' es irregular en tercera persona: ''has''."}'::jsonb, '{"vocab:daily_routine"}'),
('b0000003-0004-0001-0004-000000000001', 'b0000002-0000-0000-0001-000000000004', 4, 'fill_blank', '{"text": "My sister ___ often does her homework after school."}'::jsonb, '{"text": "usually", "accepted": ["usually", "always", "often", "sometimes", "rarely", "never"]}'::jsonb, NULL, '{"es": "Cualquier adverbio de frecuencia puede ir antes del verbo principal ''does''."}'::jsonb, '{"grammar:frequency_adverbs"}'),
('b0000003-0004-0001-0005-000000000001', 'b0000002-0000-0000-0001-000000000004', 5, 'translation', '{"text": "Él normalmente va al trabajo en autobús y siempre llega a tiempo."}'::jsonb, '{"text": "He usually goes to work by bus and he always arrives on time.", "accepted": ["He usually goes to work by bus and he always arrives on time.", "He usually goes to work by bus and always arrives on time."]}'::jsonb, NULL, NULL, '{"grammar:frequency_adverbs","vocab:daily_routine"}'),
('b0000003-0004-0001-0006-000000000001', 'b0000002-0000-0000-0001-000000000004', 6, 'translation', '{"text": "Ellos rara vez ven la televisión, pero siempre hacen la tarea."}'::jsonb, '{"text": "They rarely watch TV, but they always do homework.", "accepted": ["They rarely watch TV, but they always do homework.", "They rarely watch TV, but always do homework."]}'::jsonb, NULL, NULL, '{"grammar:frequency_adverbs","vocab:daily_routine"}'),
('b0000003-0004-0001-0007-000000000001', 'b0000002-0000-0000-0001-000000000004', 7, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "How often does your dad cook dinner?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "That''s nice, my mom always cooks!"}]}'::jsonb, '{"text": "He usually cooks twice a week."}'::jsonb, '["He is always tired in the morning.", "He goes to work by car.", "He has two brothers."]'::jsonb, '{"es": "La pregunta pide frecuencia sobre cocinar, así que la respuesta debe incluir un adverbio o expresión de frecuencia relacionada con esa actividad."}'::jsonb, '{"grammar:frequency_adverbs","vocab:daily_routine"}'),
('b0000003-0004-0001-0008-000000000001', 'b0000002-0000-0000-0001-000000000004', 8, 'multiple_choice', '{"text": "Which sentence correctly describes someone else''s routine?"}'::jsonb, '{"text": "My mom always gets up before seven."}'::jsonb, '["My mom always get up before seven.", "My mom get up always before seven.", "My mom always getting up before seven."]'::jsonb, '{"es": "Con ''my mom'' el verbo lleva -s: ''gets up''; el adverbio va antes del verbo principal."}'::jsonb, '{"grammar:frequency_adverbs","vocab:daily_routine"}');
